69	func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
70		// Initialize structured logger so logging.Warn/Info write to .entire/logs/ not stderr.
71		if err := logging.Init(ctx, sessionID); err != nil {
72			// Init failed — logging will use stderr fallback, non-fatal.
73			_ = err
74		}
75	
76		logCtx := logging.WithComponent(ctx, "attach")
77	
78		// Open repository once — shared across all operations.
79		repo, err := openRepository(ctx)
80		if err != nil {
81			return err
82		}
83	
84		existingState, err := validateAttachPreconditions(ctx, repo, sessionID)
85		if err != nil {
86			return err
87		}
88	
89		headCommit, err := getHeadCommit(repo)
90		if err != nil {
91			return err
92		}
93	
94		// If session already has a checkpoint, just offer to link it.
95		if existingState != nil && !existingState.LastCheckpointID.IsEmpty() {
96			cpID := existingState.LastCheckpointID.String()
97			fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, cpID)
98			if err := promptAmendCommit(logCtx, w, headCommit, cpID, force); err != nil {
99				logging.Warn(logCtx, "failed to amend commit", "error", err)
100				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpID)
101			}
102			return nil
103		}
104	
105		// Resolve agent and transcript path.
106		ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName, existingState)
107		if err != nil {
108			return err
109		}
110	
111		transcriptData, err := ag.ReadTranscript(transcriptPath)
112		if err != nil {
113			return fmt.Errorf("failed to read transcript: %w", err)
114		}
115	
116		// Normalize Gemini transcripts for storage.
117		storedTranscript := transcriptData
118		if ag.Type() == agent.AgentTypeGemini {
119			if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
120				storedTranscript = normalized
121			} else {
122				logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
123			}
124		}
125	
126		meta := extractTranscriptMetadata(transcriptData)
127	
128		// Determine checkpoint ID: reuse from HEAD if one exists, otherwise generate new.
129		checkpointID, isExistingCheckpoint := resolveCheckpointID(headCommit)
130	
131		// Write directly to entire/checkpoints/v1.
132		store := cpkg.NewGitStore(repo)
133	
134		author, err := GetGitAuthor(ctx)
135		if err != nil {
136			return fmt.Errorf("failed to get git author: %w", err)
137		}
138	
139		var prompts []string
140		if meta.FirstPrompt != "" {
141			prompts = []string{meta.FirstPrompt}
142		}
143	
144		tokenUsage := agent.CalculateTokenUsage(logCtx, ag, transcriptData, 0, "")
145	
146		_, redactSpan := perf.Start(ctx, "redact_transcript")
147		redactedTranscript, redactErr := redact.JSONLBytes(storedTranscript)
148		redactSpan.End()
149		if redactErr != nil {
150			return fmt.Errorf("failed to redact transcript: %w", redactErr)
151		}
152	
153		writeOpts := cpkg.WriteCommittedOptions{
154			CheckpointID: checkpointID,
155			SessionID:    sessionID,
156			Strategy:     strategy.StrategyNameManualCommit,
157			Transcript:   redactedTranscript,
158			Prompts:      prompts,
159			AuthorName:   author.Name,
160			AuthorEmail:  author.Email,
161			Agent:        ag.Type(),
162			Model:        meta.Model,
163			TokenUsage:   tokenUsage,
164		}
165	
166		if compacted := compactTranscriptForStartLine(logCtx, redactedTranscript.Bytes(), cpkg.CommittedMetadata{
167			CheckpointID: checkpointID,
168			Agent:        ag.Type(),
169		}, 0); compacted != nil {
170			writeOpts.CompactTranscript = compacted
171		}
172	
173		v2Only := settings.IsCheckpointsV2OnlyEnabled(logCtx)
174		if !v2Only {
175			if err := store.WriteCommitted(ctx, writeOpts); err != nil {
176				return fmt.Errorf("failed to write checkpoint: %w", err)
177			}
178		}
179		// IsCheckpointsV2Enabled is true whenever v2Only is true, so this covers both
180		// the v2-only and dual-write paths. Only v2-only propagates the error.
181		if settings.IsCheckpointsV2Enabled(logCtx) {
182			if err := writeAttachCheckpointV2(logCtx, repo, writeOpts); err != nil {
183				if v2Only {
184					return fmt.Errorf("failed to write checkpoint to v2: %w", err)
185				}
186				logging.Warn(logCtx, "attach v2 dual-write failed", "error", err)
187			}
188		}
189	
190		// Create or update session state.
191		if err := saveAttachSessionState(logCtx, existingState, sessionID, ag.Type(), transcriptPath, checkpointID, meta, tokenUsage); err != nil {
192			logging.Warn(logCtx, "failed to save session state", "error", err)
193		}
194	
195		fmt.Fprintf(w, "Attached session %s\n", sessionID)
196		if isExistingCheckpoint {
197			fmt.Fprintf(w, "  Added to existing checkpoint %s\n", checkpointID)
198			return nil
199		}
200	
201		fmt.Fprintf(w, "  Created checkpoint %s\n", checkpointID)
202		cpIDStr := checkpointID.String()
203		if err := promptAmendCommit(logCtx, w, headCommit, cpIDStr, force); err != nil {
204			logging.Warn(logCtx, "failed to amend commit", "error", err)
205			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpIDStr)
206		}
207	
208		return nil
209	}
210	
211	// writeAttachCheckpointV2 writes attach-created checkpoints into the v2 refs.
212	func writeAttachCheckpointV2(ctx context.Context, repo *git.Repository, opts cpkg.WriteCommittedOptions) error {
213		v2Store := cpkg.NewV2GitStore(repo, strategy.ResolveCheckpointURL(ctx, "origin"))
214		if err := v2Store.WriteCommitted(ctx, opts); err != nil {
215			return fmt.Errorf("v2 write committed: %w", err)
216		}
217		return nil
218	}
219	
220	// getHeadCommit returns the HEAD commit object.
221	func getHeadCommit(repo *git.Repository) (*object.Commit, error) {
222		headRef, err := repo.Head()
223		if err != nil {
224			return nil, fmt.Errorf("failed to get HEAD: %w", err)
225		}
226		commit, err := repo.CommitObject(headRef.Hash())
227		if err != nil {
228			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
229		}
230		return commit, nil
231	}
232	
233	// resolveCheckpointID returns the checkpoint ID to use for the attach.
234	// If HEAD already has an Entire-Checkpoint trailer, reuses that ID (the session
235	// gets added as an additional session in the existing checkpoint).
236	// Otherwise generates a new ID.
237	func resolveCheckpointID(headCommit *object.Commit) (id.CheckpointID, bool) {
238		existing := trailers.ParseAllCheckpoints(headCommit.Message)
239		if len(existing) > 0 {
240			return existing[len(existing)-1], true
241		}
242	
243		cpID, err := id.Generate()
244		if err != nil {
245			// Generation only fails if crypto/rand fails — extremely unlikely.
246			// Fall back to empty which will cause WriteCommitted to fail with a clear error.
247			return id.EmptyCheckpointID, false
248		}
249		return cpID, false
250	}
251	
252	// saveAttachSessionState creates or updates the session state file for the attached session.
253	// If existingState is non-nil, it is updated in place (avoids a redundant disk load).
254	func saveAttachSessionState(ctx context.Context, existingState *session.State, sessionID string, agentType types.AgentType, transcriptPath string, checkpointID id.CheckpointID, meta transcriptMetadata, tokenUsage *agent.TokenUsage) error {
255		stateStore, err := session.NewStateStore(ctx)
256		if err != nil {
257			return fmt.Errorf("failed to open session store: %w", err)
258		}
259	
260		now := time.Now()
261		state := existingState
262		if state == nil {
263			state = &session.State{
264				SessionID: sessionID,
265				StartedAt: now,
266			}
267		}
268	
269		state.CLIVersion = versioninfo.Version
270		state.AttachedManually = true
271		state.AgentType = agentType
272		state.TranscriptPath = transcriptPath
273		state.LastCheckpointID = checkpointID
274		state.Phase = session.PhaseEnded
275		state.LastInteractionTime = &now
276		if meta.TurnCount > 0 {
277			state.SessionTurnCount = meta.TurnCount
278		}
279		if meta.Model != "" {
280			state.ModelName = meta.Model
281		}
282		if meta.FirstPrompt != "" {
283			state.LastPrompt = meta.FirstPrompt
284		}
285		if tokenUsage != nil {
286			state.TokenUsage = tokenUsage
287		}
288	
289		if err := stateStore.Save(ctx, state); err != nil {
290			return fmt.Errorf("failed to save session state: %w", err)
291		}
292		return nil
293	}
294	
295	// validateAttachPreconditions checks session ID format and git repo state.
296	// Returns the existing session state if the session is already tracked (nil if new).
297	func validateAttachPreconditions(ctx context.Context, repo *git.Repository, sessionID string) (*session.State, error) {
298		if err := validation.ValidateSessionID(sessionID); err != nil {
299			return nil, fmt.Errorf("invalid session ID: %w", err)
300		}
301	
302		if strategy.IsEmptyRepository(repo) {
303			return nil, errors.New("repository has no commits yet — make an initial commit before running attach")
304		}
305	
306		store, err := session.NewStateStore(ctx)
307		if err != nil {
308			return nil, fmt.Errorf("failed to open session store: %w", err)
309		}
310		existing, err := store.Load(ctx, sessionID)
311		if err != nil {
312			return nil, fmt.Errorf("failed to check existing session: %w", err)
313		}
314	
315		return existing, nil
316	}
317	
318	// resolveAgentAndTranscript resolves the agent and transcript path.
319	// For existing sessions, resolves the agent from session state's AgentType.
320	// For new sessions, uses the --agent flag with auto-detection fallback.
321	func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, existingState *session.State) (agent.Agent, string, error) {
322		ag, err := resolveAgent(existingState, agentName)
323		if err != nil {
324			return nil, "", err
325		}
326	
327		transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
328		if err != nil {
329			// Auto-detect: try all other agents.
330			detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
331			if detectErr != nil {
332				return nil, "", fmt.Errorf("%w (also tried auto-detecting other agents: %w)", err, detectErr)
333			}
334			ag = detectedAg
335			transcriptPath = detectedPath
336			logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
337			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
338		}
339	
340		return ag, transcriptPath, nil
341	}
342	
343	// resolveAgent resolves the agent to use. For existing sessions with an AgentType,
344	// uses agent.GetByAgentType. Otherwise falls back to the --agent flag.
345	func resolveAgent(existingState *session.State, agentName types.AgentName) (agent.Agent, error) {
346		if existingState != nil && existingState.AgentType != "" {
347			ag, err := agent.GetByAgentType(existingState.AgentType)
348			if err == nil {
349				return ag, nil
350			}
351			// Fall through to flag-based resolution.
352		}
353		ag, err := agent.Get(agentName)
354		if err != nil {
355			return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
356		}
357		return ag, nil
358	}
359	
360	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
361	// project directories if needed.
362	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
363		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
364		if err != nil {
365			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
366		}
367		// Only call PrepareTranscript when the file already exists — it flushes
368		// in-progress writes, but can't conjure a file that was never started.
369		// This avoids agents like Cursor polling for 3s on non-existent files
370		// during auto-detection.
371		if _, statErr := os.Stat(transcriptPath); statErr == nil {
372			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
373				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
374					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
375				}
376			}
377			return transcriptPath, nil
378		}
379		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
380		if searchErr == nil {
381			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
382			return found, nil
383		}
384		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
385		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
386	}
387	
388	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
389	// transcript resolution succeeds for the given session ID.
390	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
391		for _, name := range agent.List() {
392			if name == skip {
393				continue
394			}
395			ag, err := agent.Get(name)
396			if err != nil {
397				continue
398			}
399			path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
400			if resolveErr != nil {
401				logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
402				continue
403			}
404			return ag, path, nil
405		}
406		return nil, "", errors.New("transcript not found for any registered agent")
407	}
408	
409	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
410	// When force is true, it amends without prompting.
411	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
412		shortHash := headCommit.Hash.String()[:7]
413		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
414	
415		// Skip amending if this exact checkpoint ID is already in the commit.
416		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
417			if existing.String() == checkpointIDStr {
418				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
419				return nil
420			}
421		}
422	
423		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
424	
425		amend := true
426		if !force {
427			if !interactive.CanPromptInteractively() {
428				// Non-interactive: can't prompt, print trailer for manual use.
429				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
430				return nil
431			}
432			form := NewAccessibleForm(
433				huh.NewGroup(
434					huh.NewConfirm().
435						Title("Amend the last commit in this branch?").
436						Affirmative("Y").
437						Negative("n").
438						Value(&amend),
439				),
440			)
441			if err := form.Run(); err != nil {
442				return fmt.Errorf("prompt failed: %w", err)
443			}
444		}
445	
446		if !amend {
447			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
448			return nil
449		}
450	
451		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
452	
453		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
454		if output, err := cmd.CombinedOutput(); err != nil {
455			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
456		}
457	
458		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
459		return nil
460	}
