403	// run executes a subcommand on the external binary and returns stdout bytes.
404	// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
405	// included in the returned error.
406	func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
407		// Apply a default timeout when the caller hasn't set a deadline, so a hung
408		// external binary can't block the CLI (or git hooks) indefinitely.
409		if _, ok := ctx.Deadline(); !ok {
410			var cancel context.CancelFunc
411			ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
412			defer cancel()
413		}
414		cmd := exec.CommandContext(ctx, e.binaryPath, args...)
415		// Ensure I/O goroutines are released shortly after the process is killed,
416		// so cmd.Run() doesn't block waiting for pipe reads.
417		cmd.WaitDelay = 3 * time.Second
418	
419		// Set environment: repo root + protocol version
420		cmd.Env = append(cmd.Environ(),
421			"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
422		)
423		if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
424			cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
425			cmd.Dir = repoRoot
426		}
427	
428		if stdin != nil {
429			cmd.Stdin = bytes.NewReader(stdin)
430		}
431	
432		const maxOutputBytes = 10 * 1024 * 1024 // 10 MB
433	
434		var stdoutBuf, stderrBuf bytes.Buffer
435		stdoutLW := &limitedWriter{buf: &stdoutBuf, limit: maxOutputBytes}
436		stderrLW := &limitedWriter{buf: &stderrBuf, limit: maxOutputBytes}
437		cmd.Stdout = stdoutLW
438		cmd.Stderr = stderrLW
439	
440		if err := cmd.Run(); err != nil {
441			errMsg := strings.TrimSpace(stderrBuf.String())
442			if errMsg != "" {
443				return nil, fmt.Errorf("%s: %s", args[0], errMsg)
444			}
445			return nil, fmt.Errorf("%s: %w", args[0], err)
446		}
447	
448		if stdoutLW.truncated {
449			return nil, fmt.Errorf("%s: output exceeded %d byte limit", args[0], maxOutputBytes)
450		}
451	
452		return stdoutBuf.Bytes(), nil
453	}
454	
455	// --- Helpers ---
456	
457	// limitedWriter wraps a bytes.Buffer and stops writing after limit bytes,
458	// preventing unbounded memory growth from external process output.
459	type limitedWriter struct {
460		buf       *bytes.Buffer
461		limit     int
462		truncated bool
463	}
464	
465	func (w *limitedWriter) Write(p []byte) (int, error) {
466		remaining := w.limit - w.buf.Len()
467		if remaining <= 0 {
468			w.truncated = true
469			return len(p), nil // discard, but report success so the process isn't killed
470		}
471		if len(p) > remaining {
472			p = p[:remaining]
473			w.truncated = true
474		}
475		n, err := w.buf.Write(p)
476		if err != nil {
477			return n, fmt.Errorf("writing to limited buffer: %w", err)
478		}
479		return n, nil
480	}
481	
482	func marshalHookInput(input *agent.HookInput) ([]byte, error) {
483		if input == nil {
484			return []byte("{}"), nil
485		}
486		j := HookInputJSON{
487			HookType:   string(input.HookType),
488			SessionID:  input.SessionID,
489			SessionRef: input.SessionRef,
490			Timestamp:  input.Timestamp.Format(time.RFC3339),
491			UserPrompt: input.UserPrompt,
492			ToolName:   input.ToolName,
493			ToolUseID:  input.ToolUseID,
494			ToolInput:  input.ToolInput,
495			RawData:    input.RawData,
496		}
497		data, err := json.Marshal(j)
498		if err != nil {
499			return nil, fmt.Errorf("marshal hook input: %w", err)
500		}
501		return data, nil
502	}
503	
504	func marshalAgentSession(s *agent.AgentSession) ([]byte, error) {
505		j := AgentSessionJSON{
506			SessionID:     s.SessionID,
507			AgentName:     string(s.AgentName),
508			RepoPath:      s.RepoPath,
509			SessionRef:    s.SessionRef,
510			StartTime:     s.StartTime.Format(time.RFC3339),
511			NativeData:    s.NativeData,
512			ModifiedFiles: s.ModifiedFiles,
513			NewFiles:      s.NewFiles,
514			DeletedFiles:  s.DeletedFiles,
515		}
516		data, err := json.Marshal(j)
517		if err != nil {
518			return nil, fmt.Errorf("marshal agent session: %w", err)
519		}
520		return data, nil
521	}
522	
523	func unmarshalAgentSession(j *AgentSessionJSON) (*agent.AgentSession, error) {
524		var startTime time.Time
525		if j.StartTime != "" {
526			var err error
527			startTime, err = time.Parse(time.RFC3339, j.StartTime)
528			if err != nil {
529				return nil, fmt.Errorf("invalid start_time: %w", err)
530			}
531		}
532		return &agent.AgentSession{
533			SessionID:     j.SessionID,
534			AgentName:     types.AgentName(j.AgentName),
535			RepoPath:      j.RepoPath,
536			SessionRef:    j.SessionRef,
537			StartTime:     startTime,
538			NativeData:    j.NativeData,
539			ModifiedFiles: j.ModifiedFiles,
540			NewFiles:      j.NewFiles,
541			DeletedFiles:  j.DeletedFiles,
542		}, nil
543	}
544	
545	func convertTokenUsage(r *TokenUsageResponse) *agent.TokenUsage {
546		if r == nil {
547			return nil
548		}
549		usage := &agent.TokenUsage{
550			InputTokens:         r.InputTokens,
551			CacheCreationTokens: r.CacheCreationTokens,
552			CacheReadTokens:     r.CacheReadTokens,
553			OutputTokens:        r.OutputTokens,
554			APICallCount:        r.APICallCount,
555		}
556		if r.SubagentTokens != nil {
557			usage.SubagentTokens = convertTokenUsage(r.SubagentTokens)
558		}
559		return usage
560	}
