// run executes a subcommand on the external binary and returns stdout bytes.
// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
// included in the returned error.
func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
	// Apply a default timeout when the caller hasn't set a deadline, so a hung
	// external binary can't block the CLI (or git hooks) indefinitely.
	if _, ok := ctx.Deadline(); !ok {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
		defer cancel()
	}
	cmd := exec.CommandContext(ctx, e.binaryPath, args...)
	// Ensure I/O goroutines are released shortly after the process is killed,
	// so cmd.Run() doesn't block waiting for pipe reads.
	cmd.WaitDelay = 3 * time.Second

	// Set environment: repo root + protocol version
	cmd.Env = append(cmd.Environ(),
		"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
	)
	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
		cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
		cmd.Dir = repoRoot
	}

	if stdin != nil {
		cmd.Stdin = bytes.NewReader(stdin)
	}

	const maxOutputBytes = 10 * 1024 * 1024 // 10 MB

	var stdoutBuf, stderrBuf bytes.Buffer
	stdoutLW := &limitedWriter{buf: &stdoutBuf, limit: maxOutputBytes}
	stderrLW := &limitedWriter{buf: &stderrBuf, limit: maxOutputBytes}
	cmd.Stdout = stdoutLW
	cmd.Stderr = stderrLW

	if err := cmd.Run(); err != nil {
		errMsg := strings.TrimSpace(stderrBuf.String())
		if errMsg != "" {
			return nil, fmt.Errorf("%s: %s", args[0], errMsg)
		}
		return nil, fmt.Errorf("%s: %w", args[0], err)
	}

	if stdoutLW.truncated {
		return nil, fmt.Errorf("%s: output exceeded %d byte limit", args[0], maxOutputBytes)
	}

	return stdoutBuf.Bytes(), nil
}

// --- Helpers ---

// limitedWriter wraps a bytes.Buffer and stops writing after limit bytes,
// preventing unbounded memory growth from external process output.
type limitedWriter struct {
	buf       *bytes.Buffer
	limit     int
	truncated bool
}

func (w *limitedWriter) Write(p []byte) (int, error) {
	remaining := w.limit - w.buf.Len()
	if remaining <= 0 {
		w.truncated = true
		return len(p), nil // discard, but report success so the process isn't killed
	}
	if len(p) > remaining {
		p = p[:remaining]
		w.truncated = true
	}
	n, err := w.buf.Write(p)
	if err != nil {
		return n, fmt.Errorf("writing to limited buffer: %w", err)
	}
	return n, nil
}

func marshalHookInput(input *agent.HookInput) ([]byte, error) {
	if input == nil {
		return []byte("{}"), nil
	}
	j := HookInputJSON{
		HookType:   string(input.HookType),
		SessionID:  input.SessionID,
		SessionRef: input.SessionRef,
		Timestamp:  input.Timestamp.Format(time.RFC3339),
		UserPrompt: input.UserPrompt,
		ToolName:   input.ToolName,
		ToolUseID:  input.ToolUseID,
		ToolInput:  input.ToolInput,
		RawData:    input.RawData,
	}
	data, err := json.Marshal(j)
	if err != nil {
		return nil, fmt.Errorf("marshal hook input: %w", err)
	}
	return data, nil
}

func marshalAgentSession(s *agent.AgentSession) ([]byte, error) {
	j := AgentSessionJSON{
		SessionID:     s.SessionID,
		AgentName:     string(s.AgentName),
		RepoPath:      s.RepoPath,
		SessionRef:    s.SessionRef,
		StartTime:     s.StartTime.Format(time.RFC3339),
		NativeData:    s.NativeData,
		ModifiedFiles: s.ModifiedFiles,
		NewFiles:      s.NewFiles,
		DeletedFiles:  s.DeletedFiles,
	}
	data, err := json.Marshal(j)
	if err != nil {
		return nil, fmt.Errorf("marshal agent session: %w", err)
	}
	return data, nil
}

func unmarshalAgentSession(j *AgentSessionJSON) (*agent.AgentSession, error) {
	var startTime time.Time
	if j.StartTime != "" {
		var err error
		startTime, err = time.Parse(time.RFC3339, j.StartTime)
		if err != nil {
			return nil, fmt.Errorf("invalid start_time: %w", err)
		}
	}
	return &agent.AgentSession{
		SessionID:     j.SessionID,
		AgentName:     types.AgentName(j.AgentName),
		RepoPath:      j.RepoPath,
		SessionRef:    j.SessionRef,
		StartTime:     startTime,
		NativeData:    j.NativeData,
		ModifiedFiles: j.ModifiedFiles,
		NewFiles:      j.NewFiles,
		DeletedFiles:  j.DeletedFiles,
	}, nil
}

func convertTokenUsage(r *TokenUsageResponse) *agent.TokenUsage {
	if r == nil {
		return nil
	}
	usage := &agent.TokenUsage{
		InputTokens:         r.InputTokens,
		CacheCreationTokens: r.CacheCreationTokens,
		CacheReadTokens:     r.CacheReadTokens,
		OutputTokens:        r.OutputTokens,
		APICallCount:        r.APICallCount,
	}
	if r.SubagentTokens != nil {
		usage.SubagentTokens = convertTokenUsage(r.SubagentTokens)
	}
	return usage
}

package external

import (
	"context"
	"log/slog"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const (
	binaryPrefix = "entire-agent-"
	osWindows    = "windows"
)

// discoveryTimeout caps the total time spent scanning $PATH for external agents.
const discoveryTimeout = 10 * time.Second

// DiscoverAndRegister scans $PATH for executables matching "entire-agent-<name>",
// calls their "info" subcommand, and registers them in the agent registry.
// Binaries whose name conflicts with an already-registered agent are skipped.
// Errors during discovery are logged but do not prevent other agents from loading.
// Discovery is skipped when the external_agents setting is not enabled.
func DiscoverAndRegister(ctx context.Context) {
	if !settings.IsExternalAgentsEnabled(ctx) {
		logging.Debug(ctx, "external agent discovery disabled (external_agents not enabled in settings)")
		return
	}
	discoverAndRegister(ctx)
}

// DiscoverAndRegisterAlways is like DiscoverAndRegister but bypasses the
// external_agents settings check. Use this in interactive setup flows where
// the user explicitly chooses agents.
func DiscoverAndRegisterAlways(ctx context.Context) {
	discoverAndRegister(ctx)
}

// discoverAndRegister contains the shared scanning logic for external agent discovery.
func discoverAndRegister(ctx context.Context) {
	ctx, cancel := context.WithTimeout(ctx, discoveryTimeout)
	defer cancel()

	pathEnv := os.Getenv("PATH")
	if pathEnv == "" {
		return
	}

	// Collect already-registered names to avoid conflicts.
	registered := make(map[types.AgentName]bool)
	for _, name := range agent.List() {
		registered[name] = true
	}

	seen := make(map[string]bool) // deduplicate binaries across PATH dirs
	for _, dir := range filepath.SplitList(pathEnv) {
		if ctx.Err() != nil {
			logging.Debug(ctx, "external agent discovery timed out")
			return
		}

		matches, err := filepath.Glob(filepath.Join(dir, binaryPrefix+"*"))
		if err != nil {
			continue // skip unreadable directories
		}
		for _, binPath := range matches {
			if ctx.Err() != nil {
				logging.Debug(ctx, "external agent discovery timed out")
				return
			}

			name := filepath.Base(binPath)
			if seen[name] {
				continue
			}
			seen[name] = true

			// Strip Windows executable extensions (.exe, .bat) before deriving agent name.
			// On Unix, binaries have no extension, so this is a no-op.
			cleanName := stripExeExt(name)
			agentName := types.AgentName(strings.TrimPrefix(cleanName, binaryPrefix))
			if registered[agentName] {
				logging.Debug(ctx, "skipping external agent (name conflict with built-in)",
					slog.String("binary", name),
					slog.String("agent", string(agentName)))
				continue
			}

			finfo, err := os.Stat(binPath) //nolint:gosec // PATH entries are trusted
			if err != nil || finfo.IsDir() {
				continue
			}
			// Check executable bit (on Unix; Windows doesn't set execute bits)
			if runtime.GOOS != osWindows && finfo.Mode()&0o111 == 0 {
				continue
			}

			ea, err := New(ctx, binPath)
			if err != nil {
				logging.Debug(ctx, "skipping external agent (info failed)",
					slog.String("binary", binPath),
					slog.String("error", err.Error()))
				continue
			}

			// Wrap with capability interfaces and register
			wrapped, err := Wrap(ea)
			if err != nil {
				logging.Debug(ctx, "skipping external agent (wrap failed)",
					slog.String("binary", binPath),
					slog.String("error", err.Error()))
				continue
			}
			agent.Register(agentName, func() agent.Agent {
				return wrapped
			})
			registered[agentName] = true

			logging.Debug(ctx, "registered external agent",
				slog.String("name", string(agentName)),
				slog.String("type", string(ea.Type())),
				slog.String("binary", binPath))
		}
	}
}

// stripExeExt removes Windows executable extensions (.exe, .bat, .cmd) from a
// file name so that the agent name derived from the binary matches on all platforms.
// On Unix this is effectively a no-op because binaries have no extension.
func stripExeExt(name string) string {
	switch strings.ToLower(filepath.Ext(name)) {
	case ".exe", ".bat", ".cmd":
		return strings.TrimSuffix(name, filepath.Ext(name))
	}
	return name
}

