1	package pi
2	
3	import (
4		"bufio"
5		"bytes"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11	
12		"github.com/entireio/external-agents/agents/entire-agent-pi/internal/protocol"
13	)
14	
15	// Pi JSONL entry types
16	const entryTypeMessage = "message"
17	
18	// maxScannerLine is 1 MB — large enough for Pi JSONL lines that may
19	// contain thinking blocks or full file contents in tool call arguments.
20	const maxScannerLine = 1 << 20
21	
22	func newJSONLScanner(data []byte) *bufio.Scanner {
23		s := bufio.NewScanner(bytes.NewReader(data))
24		s.Buffer(make([]byte, 0, maxScannerLine), maxScannerLine)
25		return s
26	}
27	
28	// countLines returns the number of non-empty lines in data.
29	func countLines(data []byte) int {
30		if len(data) == 0 {
31			return 0
32		}
33		n := bytes.Count(data, []byte{'\n'})
34		// Count final line if it doesn't end with newline
35		if len(data) > 0 && data[len(data)-1] != '\n' {
36			n++
37		}
38		return n
39	}
40	
41	// skipLines returns data with the first n lines removed.
42	func skipLines(data []byte, n int) []byte {
43		if n <= 0 {
44			return data
45		}
46		off := 0
47		for i := 0; i < n && off < len(data); i++ {
48			idx := bytes.IndexByte(data[off:], '\n')
49			if idx < 0 {
50				return nil // fewer lines than offset
51			}
52			off += idx + 1
53		}
54		return data[off:]
55	}
56	
57	type sessionEntry struct {
58		Type      string `json:"type"`
59		Version   int    `json:"version"`
60		ID        string `json:"id"`
61		Timestamp string `json:"timestamp"`
62		Cwd       string `json:"cwd"`
63	}
64	
65	type messageEntry struct {
66		Type    string  `json:"type"`
67		ID      string  `json:"id"`
68		Message message `json:"message"`
69	}
70	
71	type message struct {
72		Role       string          `json:"role"`
73		Content    json.RawMessage `json:"content"`
74		Timestamp  json.Number     `json:"timestamp"`
75		Usage      *tokenUsage     `json:"usage,omitempty"`
76		StopReason string          `json:"stopReason,omitempty"`
77	}
78	
79	type tokenUsage struct {
80		Input      int `json:"input"`
81		Output     int `json:"output"`
82		CacheRead  int `json:"cacheRead"`
83		CacheWrite int `json:"cacheWrite"`
84	}
85	
86	type contentItem struct {
87		Type      string          `json:"type"`
88		Text      string          `json:"text,omitempty"`
89		Name      string          `json:"name,omitempty"`
90		ID        string          `json:"id,omitempty"`
91		Arguments json.RawMessage `json:"arguments,omitempty"`
92	}
93	
94	// resolveActiveBranch parses JSONL data and returns the set of entry IDs on
95	// the active conversation branch. Pi transcripts form a tree (entries have id
96	// and parentId); the active branch is the path from the root to the last
97	// message entry in the file.
98	// Returns nil if the transcript has no tree structure or cannot be resolved.
99	func resolveActiveBranch(data []byte) map[string]bool {
100		type node struct {
101			Type     string  `json:"type"`
102			ID       string  `json:"id"`
103			ParentID *string `json:"parentId"`
104		}
105	
106		var lastMessageID string
107		hasTree := false
108		parentOf := make(map[string]string)
109	
110		scanner := newJSONLScanner(data)
111		for scanner.Scan() {
112			var n node
113			if err := json.Unmarshal(scanner.Bytes(), &n); err != nil || n.ID == "" {
114				continue
115			}
116			if n.ParentID != nil {
117				parentOf[n.ID] = *n.ParentID
118				if *n.ParentID != "" {
119					hasTree = true
120				}
121			}
122			if n.Type == entryTypeMessage {
123				lastMessageID = n.ID
124			}
125		}
126	
127		// No tree references — all entries are on the active branch.
128		if !hasTree || lastMessageID == "" {
129			return nil
130		}
131	
132		active := make(map[string]bool)
133		for cur := lastMessageID; cur != ""; {
134			if active[cur] {
135				break // cycle protection
136			}
137			active[cur] = true
138			parent, ok := parentOf[cur]
139			if !ok {
140				break
141			}
142			cur = parent
143		}
144	
145		return active
146	}
147	
148	func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
149		sessionRef := input.SessionRef
150		if sessionRef == "" {
151			return protocol.AgentSessionJSON{}, errors.New("session_ref is required")
152		}
153	
154		data, err := os.ReadFile(sessionRef)
155		if err != nil {
156			return protocol.AgentSessionJSON{}, fmt.Errorf("read session file: %w", err)
157		}
158	
159		sessionID := input.SessionID
160		if sessionID == "" {
161			sessionID = extractSessionIDFromPath(sessionRef)
162		}
163	
164		var startTime string
165		scanner := newJSONLScanner(data)
166		for scanner.Scan() {
167			var entry sessionEntry
168			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
169				continue
170			}
171			if entry.Type == "session" {
172				startTime = entry.Timestamp
173				if sessionID == "" {
174					sessionID = entry.ID
175				}
176				break
177			}
178		}
179	
180		return protocol.AgentSessionJSON{
181			SessionID:     sessionID,
182			AgentName:     "pi",
183			RepoPath:      protocol.RepoRoot(),
184			SessionRef:    sessionRef,
185			StartTime:     startTime,
186			NativeData:    data,
187			ModifiedFiles: []string{},
188			NewFiles:      []string{},
189			DeletedFiles:  []string{},
190		}, nil
191	}
192	
193	func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
194		if session.SessionRef == "" {
195			return errors.New("session_ref is required")
196		}
197		if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o700); err != nil {
198			return err
199		}
200		return os.WriteFile(session.SessionRef, session.NativeData, 0o600)
201	}
202	
203	func (a *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
204		return os.ReadFile(sessionRef)
205	}
206	
207	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
208		if maxSize <= 0 {
209			return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
210		}
211		var chunks [][]byte
212		for len(content) > 0 {
213			end := maxSize
214			if end > len(content) {
215				end = len(content)
216			}
217			chunks = append(chunks, content[:end])
218			content = content[end:]
219		}
220		return chunks, nil
221	}
222	
223	func (a *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
224		var data []byte
225		for _, chunk := range chunks {
226			data = append(data, chunk...)
227		}
228		return data, nil
229	}
230	
231	// GetTranscriptPosition returns the number of lines in the JSONL transcript.
232	// The CLI uses this value as the offset for ExtractModifiedFiles, so units
233	// must match: both use line count (consistent with Claude Code).
234	func (a *Agent) GetTranscriptPosition(path string) (int, error) {
235		data, err := os.ReadFile(path) //nolint:gosec // path from session state
236		if err != nil {
237			if os.IsNotExist(err) {
238				return 0, nil
239			}
240			return 0, err
241		}
242		return countLines(data), nil
243	}
244	
245	func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
246		data, err := os.ReadFile(path)
247		if err != nil {
248			return nil, 0, err
249		}
250	
251		totalLines := countLines(data)
252		active := resolveActiveBranch(data)
253	
254		content := skipLines(data, offset)
255	
256		seen := make(map[string]bool)
257		var files []string
258	
259		scanner := newJSONLScanner(content)
260		for scanner.Scan() {
261			var entry messageEntry
262			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
263				continue
264			}
265			if entry.Type != entryTypeMessage {
266				continue
267			}
268			if active != nil && !active[entry.ID] {
269				continue
270			}
271			if entry.Message.Role != "assistant" {
272				continue
273			}
274	
275			var items []contentItem
276			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
277				continue
278			}
279	
280			for _, item := range items {
281				if item.Type != "toolCall" {
282					continue
283				}
284				if item.Name != "write" && item.Name != "edit" {
285					continue
286				}
287				var args struct {
288					Path string `json:"path"`
289				}
290				if err := json.Unmarshal(item.Arguments, &args); err != nil {
291					continue
292				}
293				if args.Path != "" && !seen[args.Path] {
294					seen[args.Path] = true
295					files = append(files, args.Path)
296				}
297			}
298		}
299	
300		return files, totalLines, nil
301	}
302	
303	func (a *Agent) ExtractPrompts(sessionRef string, offset int) ([]string, error) {
304		data, err := os.ReadFile(sessionRef)
305		if err != nil {
306			return nil, err
307		}
308	
309		active := resolveActiveBranch(data)
310	
311		content := skipLines(data, offset)
312	
313		var prompts []string
314		scanner := newJSONLScanner(content)
315		for scanner.Scan() {
316			var entry messageEntry
317			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
318				continue
319			}
320			if entry.Type != entryTypeMessage || entry.Message.Role != "user" {
321				continue
322			}
323			if active != nil && !active[entry.ID] {
324				continue
325			}
326	
327			var items []contentItem
328			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
329				continue
330			}
331	
332			for _, item := range items {
333				if item.Type == "text" && item.Text != "" {
334					prompts = append(prompts, item.Text)
335				}
336			}
337		}
338	
339		return prompts, nil
340	}
341	
342	func (a *Agent) ExtractSummary(sessionRef string) (string, bool, error) {
343		data, err := os.ReadFile(sessionRef)
344		if err != nil {
345			return "", false, err
346		}
347	
348		active := resolveActiveBranch(data)
349	
350		var lastAssistantText string
351		scanner := newJSONLScanner(data)
352		for scanner.Scan() {
353			var entry messageEntry
354			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
355				continue
356			}
357			if entry.Type != entryTypeMessage || entry.Message.Role != "assistant" {
358				continue
359			}
360			if active != nil && !active[entry.ID] {
361				continue
362			}
363	
364			var items []contentItem
365			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
366				continue
367			}
368	
369			for _, item := range items {
370				if item.Type == "text" && item.Text != "" {
371					lastAssistantText = item.Text
372				}
373			}
374		}
375	
376		if lastAssistantText != "" {
377			return lastAssistantText, true, nil
378		}
379		return "", false, nil
380	}
381	
382	func (a *Agent) CalculateTokens(data []byte, offset int) (protocol.TokenUsageResponse, error) {
383		active := resolveActiveBranch(data)
384	
385		content := skipLines(data, offset)
386	
387		var result protocol.TokenUsageResponse
388		scanner := newJSONLScanner(content)
389		for scanner.Scan() {
390			var entry messageEntry
391			if err := json.Unmarshal(scanner.Bytes(), &entry); err != nil {
392				continue
393			}
394			if entry.Type != entryTypeMessage || entry.Message.Role != "assistant" || entry.Message.Usage == nil {
395				continue
396			}
397			if active != nil && !active[entry.ID] {
398				continue
399			}
400	
401			result.InputTokens += entry.Message.Usage.Input
402			result.OutputTokens += entry.Message.Usage.Output
403			result.CacheReadTokens += entry.Message.Usage.CacheRead
