8		"time"
9	
10		"github.com/entireio/external-agents/agents/entire-agent-pi/internal/protocol"
11	)
12	
13	const (
14		extensionDir      = ".pi/extensions/entire"
15		extensionFile     = ".pi/extensions/entire/index.ts"
16		activeSessionFile = "pi-active-session"
17	)
18	
19	// piHookPayload is the JSON the TypeScript extension sends to
20	// `entire agent hook pi <event>`, which arrives on stdin of parse-hook.
21	type piHookPayload struct {
22		Type         string `json:"type"`
23		Cwd          string `json:"cwd,omitempty"`
24		SessionFile  string `json:"session_file,omitempty"`
25		SessionID    string `json:"session_id,omitempty"`
26		Prompt       string `json:"prompt,omitempty"`
27		MessageCount int    `json:"message_count,omitempty"`
28		TurnIndex    int    `json:"turn_index,omitempty"`
29	}
30	
31	func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
32		if len(input) == 0 {
33			return nil, nil
34		}
35	
36		var payload piHookPayload
37		if err := json.Unmarshal(input, &payload); err != nil {
38			return nil, fmt.Errorf("parse hook payload: %w", err)
39		}
40	
41		sessionID := payload.SessionID
42		if sessionID == "" {
43			sessionID = extractSessionIDFromPath(payload.SessionFile)
44		}
45	
46		now := time.Now().UTC().Format(time.RFC3339)
47	
48		switch hookName {
49		case "session_start":
50			cacheSessionID(sessionID)
51			return &protocol.EventJSON{
52				Type:      1, // SessionStart
53				SessionID: sessionID,
54				Timestamp: now,
55			}, nil
56	
57		case "before_agent_start":
58			if sessionID == "" {
59				sessionID = readCachedSessionID()
60			} else {
61				cacheSessionID(sessionID)
62			}
63			// Provide the live pi session file as SessionRef so that
64			// state.TranscriptPath is populated before any mid-turn commits.
65			// Without this, the post-commit hook cannot condense when no
66			// shadow branch exists yet (no prior step checkpoints).
67			return &protocol.EventJSON{
68				Type:       2, // TurnStart
69				SessionID:  sessionID,
70				SessionRef: payload.SessionFile,
71				Prompt:     payload.Prompt,
72				Timestamp:  now,
73			}, nil
74	
75		case "agent_end":
76			if sessionID == "" {
77				sessionID = readCachedSessionID()
78			}
79			sessionRef := captureTranscript(sessionID, payload.SessionFile)
80			return &protocol.EventJSON{
81				Type:       3, // TurnEnd
82				SessionID:  sessionID,
83				SessionRef: sessionRef,
84				Timestamp:  now,
85			}, nil
86	
87		case "session_shutdown":
88			clearCachedSessionID()
89			return nil, nil
90	
91		default:
92			return nil, nil
93		}
94	}
95	
96	func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
97		root := protocol.RepoRoot()
98	
99		// If already installed and not forcing, return 0 (idempotent no-op).
100		if !force && a.AreHooksInstalled() {
101			return 0, nil
102		}
103	
104		dir := filepath.Join(root, extensionDir)
105		if err := os.MkdirAll(dir, 0o750); err != nil {
106			return 0, fmt.Errorf("create extension dir: %w", err)
107		}
108	
109		ext := generateExtension()
110	
111		path := filepath.Join(root, extensionFile)
112		if err := os.WriteFile(path, []byte(ext), 0o600); err != nil {
113			return 0, fmt.Errorf("write extension: %w", err)
114		}
115	
116		return 4, nil // 4 hooks: session_start, before_agent_start, agent_end, session_shutdown
117	}
118	
119	func (a *Agent) UninstallHooks() error {
120		root := protocol.RepoRoot()
121		dir := filepath.Join(root, extensionDir)
122		return os.RemoveAll(dir)
123	}
124	
125	func (a *Agent) AreHooksInstalled() bool {
126		root := protocol.RepoRoot()
127		path := filepath.Join(root, extensionFile)
128		_, err := os.Stat(path)
129		return err == nil
130	}
131	
132	func generateExtension() string {
133		return `import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
134	import { execFile } from "node:child_process";
135	
136	export default function (pi: ExtensionAPI) {
137	  function fireHook(hookName: string, data: Record<string, unknown>): Promise<void> {
138	    return new Promise((resolve) => {
139	      try {
140	        const child = execFile(
141	          "entire",
142	          ["hooks", "pi", hookName],
143	          {
144	            timeout: 10000,
145	            windowsHide: true,
146	          },
147	          () => resolve(),
148	        );
149	        child.stdin?.end(JSON.stringify(data));
150	      } catch {
151	        // best effort — don't block the agent
152	        resolve();
153	      }
154	    });
155	  }
156	
157	  pi.on("tool_call", async (event) => {
158	    if (event.toolName !== "bash") {
159	      return;
160	    }
161	
162	    const input = event.input as { command?: string };
163	    if (typeof input.command !== "string" || input.command.includes("GIT_TERMINAL_PROMPT=")) {
164	      return;
165	    }
166	
167	    // Pi tool subprocesses may inherit a real TTY even though the agent cannot
168	    // answer hook prompts. Disable git/Entire terminal prompts for bash calls so
169	    // Entire treats agent-driven commits as non-interactive.
170	    input.command = "export GIT_TERMINAL_PROMPT=0\n" + input.command;
171	  });
172	
173	  pi.on("session_start", async (_event, ctx) => {
174	    await fireHook("session_start", {
175	      type: "session_start",
176	      cwd: ctx.cwd,
177	      session_file: ctx.sessionManager.getSessionFile(),
178	    });
179	  });
180	
181	  pi.on("before_agent_start", async (event, ctx) => {
182	    await fireHook("before_agent_start", {
183	      type: "before_agent_start",
184	      cwd: ctx.cwd,
185	      session_file: ctx.sessionManager.getSessionFile(),
186	      prompt: event.prompt,
187	    });
188	  });
189	
190	  pi.on("agent_end", async (_event, ctx) => {
191	    await fireHook("agent_end", {
192	      type: "agent_end",
193	      cwd: ctx.cwd,
194	      session_file: ctx.sessionManager.getSessionFile(),
195	    });
196	  });
197	
198	  pi.on("session_shutdown", async () => {
199	    await fireHook("session_shutdown", {
200	      type: "session_shutdown",
201	    });
202	  });
203	}
204	`
205	}
206	
207	// cacheSessionID writes the session ID to .entire/tmp/pi-active-session.
208	func cacheSessionID(id string) {
209		if id == "" {
210			return
211		}
212		dir := protocol.DefaultSessionDir(protocol.RepoRoot())
213		_ = os.MkdirAll(dir, 0o750)
214		_ = os.WriteFile(filepath.Join(dir, activeSessionFile), []byte(id), 0o600)
215	}
216	
217	// readCachedSessionID reads the cached session ID.
218	func readCachedSessionID() string {
219		dir := protocol.DefaultSessionDir(protocol.RepoRoot())
220		data, err := os.ReadFile(filepath.Join(dir, activeSessionFile))
221		if err != nil {
222			return ""
223		}
224		return string(data)
225	}
226	
227	// clearCachedSessionID removes the cached session ID file.
228	func clearCachedSessionID() {
229		dir := protocol.DefaultSessionDir(protocol.RepoRoot())
230		_ = os.Remove(filepath.Join(dir, activeSessionFile))
231	}
232	
233	// captureTranscript copies the Pi JSONL session file to .entire/tmp/<id>.json
234	// so that Entire can read the transcript. Returns the path to the cached file.
235	func captureTranscript(sessionID, piSessionFile string) string {
236		if sessionID == "" || piSessionFile == "" {
237			return ""
238		}
239		dir := protocol.DefaultSessionDir(protocol.RepoRoot())
240		_ = os.MkdirAll(dir, 0o750)
241		dst := filepath.Join(dir, sessionID+".json")
242	
243		data, err := os.ReadFile(piSessionFile)
244		if err != nil {
245			fmt.Fprintf(os.Stderr, "entire-agent-pi: capture transcript: read %s: %v\n", piSessionFile, err)
246			return ""
247		}
248		if err := os.WriteFile(dst, data, 0o600); err != nil {
249			fmt.Fprintf(os.Stderr, "entire-agent-pi: capture transcript: write %s: %v\n", dst, err)
250			return ""
251		}
252		return dst
253	}
254	
255	// extractSessionIDFromPath extracts the UUID from a Pi session filename.
256	// Pattern: <timestamp>_<uuid>.jsonl → returns <uuid>
257	func extractSessionIDFromPath(path string) string {
258		if path == "" {
259			return ""
260		}
261		base := filepath.Base(path)
262		// Remove .jsonl extension
263		if len(base) > 6 && base[len(base)-6:] == ".jsonl" {
264			base = base[:len(base)-6]
265		}
266		// Find the UUID after the last underscore
267		for i := len(base) - 1; i >= 0; i-- {
268			if base[i] == '_' {
269				return base[i+1:]
270			}
271		}
272		return base
273	}
