366	func hookCommandBase(localDev bool) string {
367		if localDev {
368			return localDevCommandBase
369		}
370		return prodHookCommandBase
371	}
372	
373	// shellWrappedCommand wraps a hook command in "sh -c" with a /dev/null stdin
374	// redirect. IDEs typically run hook commands directly without a shell, so a
375	// bare "</dev/null" suffix is passed as a literal argument instead of being
376	// interpreted as a redirect. Wrapping in sh ensures the redirect works.
377	// The command content is built from compile-time constants (not user input).
378	func shellWrappedCommand(cmd string) string {
379		return "sh -c '" + cmd + " </dev/null'"
380	}
381	
382	func trustedCommand(localDev bool) string {
383		if localDev {
384			return localDevTrustedCmd
385		}
386		return prodTrustedCommand
387	}
388	
389	func readSettings(path string) (map[string]json.RawMessage, error) {
390		data, err := os.ReadFile(path)
391		if err != nil {
392			if os.IsNotExist(err) {
393				return map[string]json.RawMessage{}, nil
394			}
395			return nil, err
396		}
397		var settings map[string]json.RawMessage
398		if err := json.Unmarshal(data, &settings); err != nil {
399			return nil, err
400		}
401		if settings == nil {
402			settings = map[string]json.RawMessage{}
403		}
404		return settings, nil
405	}
406	
407	func readTrustedCommands(settings map[string]json.RawMessage) ([]string, error) {
408		raw, ok := settings[trustedCommandsKey]
409		if !ok {
410			return []string{}, nil
411		}
412		var commands []string
413		if err := json.Unmarshal(raw, &commands); err != nil {
414			return nil, err
415		}
416		return commands, nil
417	}
418	
419	func writeSettings(path string, settings map[string]json.RawMessage) error {
420		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
421			return err
422		}
423		data, err := marshalJSON(settings)
424		if err != nil {
425			return err
426		}
427		return os.WriteFile(path, data, 0o600)
428	}
429	
430	func marshalJSON(v any) ([]byte, error) {
431		data, err := json.MarshalIndent(v, "", "  ")
432		if err != nil {
433			return nil, err
434		}
435		return append(data, '\n'), nil
436	}
437	
438	func (a *Agent) generateAndCacheSessionID() string {
439		sessionID := generateSessionID()
440		cachePath := a.sessionIDCachePath()
441		if err := os.MkdirAll(filepath.Dir(cachePath), 0o700); err == nil {
442			_ = os.WriteFile(cachePath, []byte(sessionID), 0o600)
443		}
444		return sessionID
445	}
446	
447	func (a *Agent) readCachedSessionID() string {
448		data, err := os.ReadFile(a.sessionIDCachePath())
449		if err != nil {
450			return ""
451		}
452		return strings.TrimSpace(string(data))
453	}
454	
455	func (a *Agent) clearCachedSessionID() {
456		_ = os.Remove(a.sessionIDCachePath())
457		_ = os.Remove(a.toolCallsPath())
458	}
459	
460	func (a *Agent) appendToolCall(name string, input json.RawMessage) {
461		call := kiroToolCall{Name: name, Args: input}
462		line, err := json.Marshal(call)
463		if err != nil {
464			return
465		}
466		path := a.toolCallsPath()
467		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
468			return
469		}
470		f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
471		if err != nil {
472			return
473		}
474		defer func() { _ = f.Close() }()
475		_, _ = f.Write(append(line, '\n'))
476	}
477	
478	func (a *Agent) readAndClearToolCalls() []kiroToolCall {
479		path := a.toolCallsPath()
480		data, err := os.ReadFile(path)
481		if err != nil {
482			return nil
483		}
484		_ = os.Remove(path)
485	
486		var calls []kiroToolCall
487		for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
488			if line == "" {
489				continue
490			}
491			var call kiroToolCall
492			if err := json.Unmarshal([]byte(line), &call); err == nil {
493				calls = append(calls, call)
494			}
495		}
496		return calls
497	}
498	
499	func (a *Agent) toolCallsPath() string {
500		return filepath.Join(protocol.RepoRoot(), ".entire", "tmp", toolCallsFile)
501	}
502	
503	func (a *Agent) sessionIDCachePath() string {
504		return filepath.Join(protocol.RepoRoot(), ".entire", "tmp", sessionIDFile)
505	}
506	
507	func fallbackStopSessionID() string {
508		return generateSessionID()
509	}
510	
511	func generateSessionID() string {
512		buf := make([]byte, 16)
513		if _, err := rand.Read(buf); err != nil {
514			return fmt.Sprintf("kiro-%d", time.Now().UnixNano())
515		}
516		return hex.EncodeToString(buf)
517	}
